/**
 * The name column's own table, and the four things that keep it honest.
 *
 * WHAT THIS COVERS. `src/confusable-names.ts` is generated by
 * `scripts/gen_confusable_names.py` from the same `unicodedata` the reference
 * cleaner calls, and `src/names.ts` reads it only where the engine's own table
 * has no name. `cli.inspect.test.ts` pins the OUTPUT against Python row by row;
 * this file pins the TABLE: that it is what the generator writes today, that it
 * covers every look-alike the engine cannot name, that it never contradicts the
 * engine where both know a codepoint, and that it stayed on the Node side.
 *
 * WHY THE TABLE IS HERE AND NOT IN THE ENGINE, WITH THE NUMBERS. The engine's
 * `unicode-names.ts` is generated for what the engine CLASSIFIES and has names
 * for only 8 of the look-alike table's 1508 nameable source codepoints. Adding
 * the other 1500 there costs 68,993 bytes of source and about 10 kB gzip in a
 * file that is 3.7 kB gzip today. The engine's shared name table is on the
 * critical path of the browser bundle and these rows would roughly triple it,
 * to widen a column only this CLI prints. The same rows on the Node side cost
 * 68 kB in `dist/main.js`, `dist/doc.js` and `dist/mcp.js`; on the Node side
 * the table is read from disk, so it lives here.
 */
import { readFileSync, readdirSync } from 'node:fs'
import { join } from 'node:path'

import { CONFUSABLES, formatCodepoint, nameOf as engineNameOf } from '@ghostchars/engine'
import type { Finding } from '@ghostchars/engine'
import { beforeAll, describe, expect, it } from 'vitest'

import { CONFUSABLE_NAMES } from '../src/confusable-names.js'
import { named, namedAll, nameOf } from '../src/names.js'

import { REPO_ROOT, pythonSkipped, requirePython, runPythonScript } from './helpers/python.js'

const GENERATOR = join(REPO_ROOT, 'cli', 'scripts', 'gen_confusable_names.py')
const TABLE = join(REPO_ROOT, 'cli', 'src', 'confusable-names.ts')
const ENGINE_DIR = join(REPO_ROOT, 'web', 'src', 'engine')

/**
 * The five look-alike source codepoints Python cannot name either.
 *
 * They are in `confusables.txt` but unassigned in the UCD build Python ships
 * here, so `unicodedata.name()` returns nothing for them and
 * `strip_invisible.py --show` prints its own `<unnamed>` placeholder. Nothing
 * this package can do makes a name appear, so they are listed rather than
 * counted, and they are the only exception this file allows.
 */
const UNNAMEABLE = [0x11dda, 0x11de0, 0x11de1, 0x16eaa, 0x16eb6]

beforeAll(() => {
  requirePython()
})

describe('the look-alike name table', () => {
  it.skipIf(pythonSkipped())('is exactly what the generator writes today', () => {
    // A hand edit, a stale checkout or a machine on a different Unicode version
    // all show up here, and the message says which command fixes it.
    const result = runPythonScript(GENERATOR, ['--check'])
    expect(result.stderr).toBe('')
    expect(result.code).toBe(0)
  })

  it('covers every look-alike the engine has no name for', () => {
    const uncovered: string[] = []
    for (const cp of CONFUSABLES.keys()) {
      if (engineNameOf(cp) !== formatCodepoint(cp)) continue
      if (CONFUSABLE_NAMES.has(cp)) continue
      uncovered.push(formatCodepoint(cp))
    }
    expect(uncovered).toEqual(UNNAMEABLE.map(formatCodepoint))
  })

  it('never contradicts the engine where both know a codepoint', () => {
    const disagreeing: string[] = []
    let overlap = 0
    for (const [cp, name] of CONFUSABLE_NAMES) {
      const fromEngine = engineNameOf(cp)
      if (fromEngine === formatCodepoint(cp)) continue
      overlap += 1
      if (fromEngine !== name) disagreeing.push(`${formatCodepoint(cp)}: ${fromEngine} vs ${name}`)
    }
    expect(disagreeing).toEqual([])
    // The measured split, pinned so the day the engine's own table grows to
    // cover look-alikes this test says so and the local table can be deleted.
    expect(CONFUSABLE_NAMES.size).toBe(1508)
    expect(overlap).toBe(8)
    expect(CONFUSABLE_NAMES.size - overlap).toBe(1500)
  })

  it('stays on the Node side: nothing in the engine reads it', () => {
    // The whole justification for a second table is that the shared engine and
    // the web bundle are untouched. An import from the engine would quietly
    // undo that, so it is asserted rather than trusted.
    const offenders = readdirSync(ENGINE_DIR, { withFileTypes: true })
      .filter((entry) => entry.isFile() && entry.name.endsWith('.ts'))
      .filter((entry) => readFileSync(join(ENGINE_DIR, entry.name), 'utf8').includes('confusable-names'))
      .map((entry) => entry.name)
    expect(offenders).toEqual([])
  })

  it('is plain ASCII and says it is generated', () => {
    const bytes = readFileSync(TABLE)
    expect(bytes.subarray(0, 60).toString('utf8')).toContain(
      'Generated by cli/scripts/gen_confusable_names.py',
    )
    const high = [...bytes].filter((byte) => byte > 0x7f)
    expect(high).toEqual([])
  })
})

describe('nameOf', () => {
  it('answers a look-alike letter with the name the reference prints', () => {
    // U+0440 CYRILLIC SMALL LETTER ER, the letter that reads as a Latin p.
    expect(nameOf(0x0440)).toBe('CYRILLIC SMALL LETTER ER')
    // U+0501 CYRILLIC SMALL LETTER KOMI DE, a row only the local table has.
    expect(nameOf(0x0501)).toBe('CYRILLIC SMALL LETTER KOMI DE')
  })

  it('keeps the engine answer where the engine has one', () => {
    expect(nameOf(0x200b)).toBe('ZERO WIDTH SPACE')
    // A variation selector is a RULE in the engine's nameOf, not a table row,
    // which is why "the engine has no name" is asked by comparing against the
    // placeholder rather than by reading the engine's map.
    expect(nameOf(0xfe0f)).toBe('VARIATION SELECTOR-16')
    expect(nameOf(0xe0100)).toBe('VARIATION SELECTOR-17')
  })

  it('still falls back to U+XXXX when neither table has a name', () => {
    // A noncharacter, and a look-alike the UCD build here does not assign.
    expect(nameOf(0xfdd0)).toBe('U+FDD0')
    for (const cp of UNNAMEABLE) expect(nameOf(cp)).toBe(formatCodepoint(cp))
  })
})

describe('renaming a finding', () => {
  const finding: Finding = {
    index: 0,
    line: 1,
    col: 1,
    cp: 0x0440,
    name: 'U+0440',
    kind: 'confusable',
    flag: '--confusables',
    action: 'found-not-targeted',
    replacement: 'p',
  }

  it('replaces the name and nothing else', () => {
    expect(named(finding)).toEqual({ ...finding, name: 'CYRILLIC SMALL LETTER ER' })
  })

  it('leaves a finding the engine already named alone', () => {
    const zwsp: Finding = {
      index: 0,
      line: 1,
      col: 1,
      cp: 0x200b,
      name: 'ZERO WIDTH SPACE',
      kind: 'invisible',
      flag: 'default',
      action: 'removed',
    }
    expect(named(zwsp)).toEqual(zwsp)
    expect(namedAll([zwsp, finding])).toEqual([
      zwsp,
      { ...finding, name: 'CYRILLIC SMALL LETTER ER' },
    ])
  })
})
